// A deep, immutable snapshot of one DPB reference slot at a show_existing event.
class _SlotSnap {
  final bool valid;
  final int frameType;
  final int orderHint;
  final List<List<int>> y, u, v;
  final int width, height;
  final bool hasGrain;
  _SlotSnap(
    this.valid,
    this.frameType,
    this.orderHint,
    this.y,
    this.u,
    this.v,
    this.width,
    this.height,
    this.hasGrain,
  );
}

class _Event {
  final int payloadStart, payloadEnd;
  final int frameToShowMapIdx, refreshFrameFlags, orderHint, frameType;
  final List<_SlotSnap> slots;
  _Event(
    this.payloadStart,
    this.payloadEnd,
    this.frameToShowMapIdx,
    this.refreshFrameFlags,
    this.orderHint,
    this.frameType,
    this.slots,
  );
}

List<List<int>> _deep(List<List<int>> p) => [
  for (final r in p) [...r],
];

List<List<int>> _rows(Object o) => [
  for (final r in o as List) (r as List).cast<int>().toList(),
];

_SlotSnap _slotFrom(List s) => _SlotSnap(
  (s[0] as int) == 1,
  s[1] as int,
  s[2] as int,
  _rows(s[6]),
  _rows(s[7]),
  _rows(s[8]),
  s[3] as int,
  s[4] as int,
  (s[5] as int) == 1,
);

_Event _eventFrom(List e) => _Event(
  e[0] as int,
  e[1] as int,
  e[2] as int,
  e[3] as int,
  e[4] as int,
  e[5] as int,
  [for (final s in e[6] as List) _slotFrom(s as List)],
);

HarborRefFrame _toRef(_SlotSnap s) => HarborRefFrame(
  planeY: _deep(s.y),
  planeU: _deep(s.u),
  planeV: _deep(s.v),
  orderHint: s.orderHint,
  width: s.width,
  height: s.height,
  frameType: s.frameType,
);

int _planeDiffs(List<List<int>> a, List<List<int>> b) {
  var n = 0;
  expect(a.length, equals(b.length), reason: 'plane row count');
  for (var r = 0; r < a.length; r++) {
    expect(a[r].length, equals(b[r].length), reason: 'plane col count');
    for (var c = 0; c < a[r].length; c++) {
      if (a[r][c] != b[r][c]) n++;
    }
  }
  return n;
}

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  const maxBytes = 16;

  test(
    'HarborFrameHeaderParse + DPB: show_existing_frame bit-exact vs SW',
    () async {
      final buf = Uint8List.fromList(_obu);

      // SW golden (captured): each show_existing header window plus the live
      // (pre-refresh) reference state.
      final events = [for (final e in _eventsData) _eventFrom(e as List)];

      expect(events.length, equals(2), reason: 'stream must carry two ARFs');
      // Both re-display a non-key ARF, so refresh_frame_flags == 0.
      for (final e in events) {
        expect(
          e.frameType,
          isNot(equals(_keyFrame)),
          reason: 'shown ARF must be inter',
        );
        expect(
          e.refreshFrameFlags,
          equals(0),
          reason: 'non-key show_existing refresh must be 0',
        );
        expect(
          e.slots[e.frameToShowMapIdx].hasGrain,
          isFalse,
          reason: 'this stream has no film grain',
        );
      }

      final p = HarborFrameHeaderParse(maxBytes: maxBytes);
      final clk = SimpleClockGenerator(10).clk;
      final reset = Logic(name: 'reset');
      final start = Logic(name: 'start');
      final bytes = Logic(name: 'bytes', width: maxBytes * 8);
      final iFrameId = Logic(name: 'i_frame_id');
      final iReduced = Logic(name: 'i_reduced');
      final iDecModel = Logic(name: 'i_dec_model');
      final iDeltaIdM2 = Logic(name: 'i_delta_id', width: 4);
      final iAddIdM1 = Logic(name: 'i_add_id', width: 3);
      final iShownType = Logic(name: 'i_shown_type', width: 2);
      final iShownOrder = Logic(name: 'i_shown_order', width: 8);

      void tie(String port, int width, [int value = 0]) =>
          p.input(port).srcConnection! <= Const(value, width: width);

      p.input('clk').srcConnection! <= clk;
      p.input('reset').srcConnection! <= reset;
      p.input('start').srcConnection! <= start;
      p.input('bytes').srcConnection! <= bytes;
      p.input('seq_reduced_still_picture').srcConnection! <= iReduced;
      p.input('seq_frame_id_numbers_present').srcConnection! <= iFrameId;
      p.input('seq_delta_frame_id_length_minus2').srcConnection! <= iDeltaIdM2;
      p.input('seq_additional_frame_id_length_minus1').srcConnection! <=
          iAddIdM1;
      p.input('seq_decoder_model_info_present').srcConnection! <= iDecModel;
      p.input('shown_frame_type').srcConnection! <= iShownType;
      p.input('shown_order_hint').srcConnection! <= iShownOrder;
      // The remaining seq inputs are unused on the show_existing path.
      tie('seq_force_screen_content_tools', 2);
      tie('seq_force_integer_mv', 2);
      tie('seq_order_hint_bits', 4);
      tie('seq_enable_order_hint', 1);
      tie('seq_frame_width_bits_minus1', 4);
      tie('seq_frame_height_bits_minus1', 4);
      tie('seq_max_frame_width_minus1', 32);
      tie('seq_max_frame_height_minus1', 32);
      tie('seq_enable_superres', 1);
      tie('seq_use_128x128_superblock', 1);
      tie('seq_num_planes', 2);
      tie('seq_separate_uv_delta_q', 1);
      tie('seq_enable_cdef', 1);
      tie('seq_enable_restoration', 1);
      tie('seq_subsampling_x', 1);
      tie('seq_subsampling_y', 1);
      tie('seq_film_grain_params_present', 1);
      tie('seq_enable_ref_frame_mvs', 1);
      tie('seq_enable_warped_motion', 1);

      // Hardware DPB control plane: drives the show_en / show_idx port so a
      // show_existing pulse copies the shown slot into the refreshed slots.
      final ctl = HarborDpbControl();
      final ctlReset = Logic(name: 'ctl_reset');
      final refreshEn = Logic(name: 'refresh_en');
      final refreshFlags = Logic(name: 'refresh_flags', width: 8);
      final orderHintIn = Logic(name: 'order_hint_in', width: 8);
      final handleIn = Logic(name: 'handle_in', width: 4);
      final showEn = Logic(name: 'show_en');
      final showIdx = Logic(name: 'show_idx', width: 3);
      ctl.input('clk').srcConnection! <= clk;
      ctl.input('reset').srcConnection! <= ctlReset;
      ctl.input('refresh_en').srcConnection! <= refreshEn;
      ctl.input('refresh_flags').srcConnection! <= refreshFlags;
      ctl.input('order_hint_in').srcConnection! <= orderHintIn;
      ctl.input('handle_in').srcConnection! <= handleIn;
      ctl.input('show_en').srcConnection! <= showEn;
      ctl.input('show_idx').srcConnection! <= showIdx;
      ctl.input('ref_frame_idx').srcConnection! <= Const(0, width: 7 * 3);
      ctl.input('sel_ref').srcConnection! <= Const(0, width: 4);

      await p.build();
      await ctl.build();

      reset.inject(1);
      start.inject(0);
      bytes.inject(0);
      iReduced.inject(0);
      iDecModel.inject(0);
      iDeltaIdM2.inject(0);
      iAddIdM1.inject(0);
      iFrameId.inject(_seqFrameIdNumbersPresent ? 1 : 0);
      iShownType.inject(0);
      iShownOrder.inject(0);
      ctlReset.inject(1);
      refreshEn.inject(0);
      refreshFlags.inject(0);
      orderHintIn.inject(0);
      handleIn.inject(0);
      showEn.inject(0);
      showIdx.inject(0);
      Simulator.setMaxSimTime(200000000);
      unawaited(Simulator.run());
      await clk.nextPosedge;

      BigInt pack(List<int> b) {
        var v = BigInt.zero;
        for (var i = 0; i < b.length; i++) {
          v |= BigInt.from(b[i] & 0xFF) << (i * 8);
        }
        return v;
      }

      int o(String name) => p.output(name).value.toInt();

      // Runs the FSM over a header window with the given shown-slot metadata.
      Future<void> run(
        int payloadStart,
        int payloadEnd,
        int shownType,
        int shownOrder,
      ) async {
        final window = List<int>.filled(maxBytes, 0);
        final src = buf.sublist(payloadStart, payloadEnd);
        for (var i = 0; i < src.length && i < maxBytes; i++) {
          window[i] = src[i];
        }
        iShownType.inject(shownType);
        iShownOrder.inject(shownOrder);
        reset.inject(1);
        await clk.nextPosedge;
        reset.inject(0);
        bytes.inject(pack(window));
        start.inject(1);
        await clk.nextPosedge;
        start.inject(0);
        var guard = 0;
        while (p.output('done').value.toInt() != 1) {
          await clk.nextPosedge;
          if (++guard > 200) fail('timeout');
        }
      }

      var totalPixelDiffs = 0;
      for (var k = 0; k < events.length; k++) {
        final e = events[k];
        final shownSlot = e.slots[e.frameToShowMapIdx];
        await run(
          e.payloadStart,
          e.payloadEnd,
          shownSlot.frameType,
          shownSlot.orderHint,
        );

        expect(o('unsupported'), equals(0), reason: 'event $k unsupported');
        expect(
          o('show_existing_frame'),
          equals(1),
          reason: 'event $k show_existing',
        );
        expect(
          o('frame_to_show_map_idx'),
          equals(e.frameToShowMapIdx),
          reason: 'event $k idx',
        );
        expect(
          o('refresh_frame_flags'),
          equals(e.refreshFrameFlags),
          reason: 'event $k refresh',
        );
        expect(o('order_hint'), equals(e.orderHint), reason: 'event $k order');
        expect(
          o('frame_type'),
          equals(e.frameType),
          reason: 'event $k frame_type',
        );

        // Drive the DPB data plane with the HW-parsed index + refresh: populate
        // all 8 slots (distinct decoded frames) and select the shown one.
        final dpb = HarborDpb();
        for (var i = 0; i < _numRefFrames; i++) {
          if (e.slots[i].valid) dpb.slots[i] = _toRef(e.slots[i]);
        }
        final shown = dpb.showExistingFrame(
          o('frame_to_show_map_idx'),
          refreshFrameFlags: o('refresh_frame_flags'),
        );
        expect(
          shown,
          isNotNull,
          reason: 'event $k shown slot must be populated',
        );
        final dy = _planeDiffs(shown!.planeY, shownSlot.y);
        final du = _planeDiffs(shown.planeU, shownSlot.u);
        final dv = _planeDiffs(shown.planeV, shownSlot.v);
        expect(
          [dy, du, dv],
          equals([0, 0, 0]),
          reason: 'event $k shown pixels: Y=$dy U=$du V=$dv',
        );
        totalPixelDiffs += dy + du + dv;
      }
      expect(
        totalPixelDiffs,
        equals(0),
        reason: 'all show_existing shown pixels bit-exact',
      );

      // Take a real show_existing header window but place a KEY_FRAME in the
      // shown slot. The SW golden is parseFrameHeader over that RefState (captured
      // as _keyIdx / _keyRefresh / _keyType / _keyShowExisting). The HW must
      // reproduce refresh_frame_flags = 0xff, frame_type = KEY_FRAME, and copy the
      // shown frame into all 8 slots.
      final e0 = events[0];
      final keyOrder = 5;
      expect(_keyShowExisting, isTrue);
      expect(_keyIdx, equals(e0.frameToShowMapIdx));
      expect(
        _keyRefresh,
        equals(0xff),
        reason: 'SW: shown keyframe refreshes all slots',
      );
      expect(_keyType, equals(_keyFrame));

      await run(e0.payloadStart, e0.payloadEnd, _keyFrame, keyOrder);
      expect(o('unsupported'), equals(0));
      expect(o('show_existing_frame'), equals(1));
      expect(o('frame_to_show_map_idx'), equals(_keyIdx));
      expect(
        o('refresh_frame_flags'),
        equals(0xff),
        reason: 'HW keyframe 0xff',
      );
      expect(o('frame_type'), equals(_keyFrame));
      expect(o('order_hint'), equals(keyOrder));

      // DPB: a 0xff refresh copies the shown keyframe into every slot.
      final dpb = HarborDpb();
      final key = HarborRefFrame(
        planeY: List.generate(
          64,
          (r) => List.generate(64, (c) => (r + c) & 0xff),
        ),
        planeU: List.generate(32, (r) => List.generate(32, (c) => c & 0xff)),
        planeV: List.generate(32, (r) => List.generate(32, (c) => r & 0xff)),
        orderHint: keyOrder,
        width: 64,
        height: 64,
        frameType: _keyFrame,
      );
      dpb.slots[e0.frameToShowMapIdx] = key;
      final shownKey = dpb.showExistingFrame(
        o('frame_to_show_map_idx'),
        refreshFrameFlags: o('refresh_frame_flags'),
      );
      expect(shownKey, isNotNull);
      for (var i = 0; i < _numRefFrames; i++) {
        expect(
          identical(dpb.slots[i], key),
          isTrue,
          reason: 'slot $i must hold the shown keyframe after 0xff refresh',
        );
      }

      // Deassert ctl reset, write two distinct frames into slots 2 and 5, then
      // pulse show_en(show_idx=2) with a 0xff refresh (the keyframe rule): every
      // slot must take slot 2's registered order_hint / handle.
      ctlReset.inject(0);
      await clk.nextPosedge;
      const ohA = 0x37, hA = 3, ohB = 0x54, hB = 6;
      refreshEn.inject(1);
      refreshFlags.inject(1 << 2);
      orderHintIn.inject(ohA);
      handleIn.inject(hA);
      await clk.nextPosedge;
      refreshFlags.inject(1 << 5);
      orderHintIn.inject(ohB);
      handleIn.inject(hB);
      await clk.nextPosedge;
      refreshEn.inject(0);
      await clk.nextPosedge;
      // show_existing of slot 2 with a keyframe-forced 0xff refresh.
      showEn.inject(1);
      showIdx.inject(2);
      refreshFlags.inject(0xff);
      await clk.nextPosedge;
      showEn.inject(0);
      refreshFlags.inject(0);
      await clk.nextPosedge;
      final ohVec = ctl.output('slot_order_hints').value;
      final hVec = ctl.output('slot_handles').value;
      expect(
        ctl.output('slot_valid').value.toInt(),
        equals(0xff),
        reason: 'all slots valid after 0xff show refresh',
      );
      for (var i = 0; i < 8; i++) {
        expect(
          ohVec.getRange(i * 8, i * 8 + 8).toInt(),
          equals(ohA),
          reason: 'ctl slot $i order_hint == shown slot 2',
        );
        expect(
          hVec.getRange(i * 4, i * 4 + 4).toInt(),
          equals(hA),
          reason: 'ctl slot $i handle == shown slot 2',
        );
      }

      print(
        'show_existing_frame: 2 ARF events + 1 keyframe case, '
        'shown pixels Y/U/V diffs = 0/0/0, refresh + fields bit-exact vs SW; '
        'HW DPB control show_en copy verified',
      );

      await Simulator.endSimulation();
    },
  );
}
